#include <algorithm>
#include <functional>
#include <map>
#include <queue>
#include <set>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

using Edges = std::vector<std::pair<int, int>>;

std::vector<int> topoOrder(int n, const Edges& edges)
{
    std::vector<std::vector<int>> adj(n);
    std::vector<int> indegree(n, 0);
    for (auto [u, v] : edges) { adj[u].push_back(v); ++indegree[v]; }
    std::priority_queue<int, std::vector<int>, std::greater<int>> ready;
    for (int u = 0; u < n; ++u)
        if (indegree[u] == 0) ready.push(u);
    std::vector<int> order;
    while (!ready.empty())
    {
        int u = ready.top();
        ready.pop();
        order.push_back(u);
        for (int v : adj[u])
            if (--indegree[v] == 0) ready.push(v);
    }
    if (static_cast<int>(order.size()) < n) return {};
    return order;
}

std::vector<int> findCycle(int n, const Edges& edges)
{
    std::vector<std::vector<int>> adj(n);
    for (auto [u, v] : edges) adj[u].push_back(v);
    enum { White, Grey, Black };
    std::vector<int> colour(n, White);
    std::vector<std::size_t> nextEdge(n, 0);
    std::vector<int> path;                                    // the current DFS path (the grey vertices, in order)
    for (int s = 0; s < n; ++s)
    {
        if (colour[s] != White) continue;
        path.push_back(s);
        colour[s] = Grey;
        while (!path.empty())
        {
            int u = path.back();
            if (nextEdge[u] == adj[u].size())
            {
                colour[u] = Black;
                path.pop_back();
                continue;
            }
            int v = adj[u][nextEdge[u]++];
            if (colour[v] == Grey)
            {
                auto start = std::find(path.begin(), path.end(), v);
                return std::vector<int>(start, path.end());
            }
            if (colour[v] == White)
            {
                colour[v] = Grey;
                path.push_back(v);
            }
        }
    }
    return {};
}

long long countPaths(int n, const Edges& edges, int from, int to)
{
    std::vector<int> order = topoOrder(n, edges);
    std::vector<std::vector<int>> adj(n);
    for (auto [u, v] : edges) adj[u].push_back(v);
    std::vector<long long> ways(n, 0);
    ways[from] = 1;
    for (int u : order)
        for (int v : adj[u]) ways[v] += ways[u];
    return ways[to];
}

std::vector<std::string> buildOrder(const std::vector<std::string>& lines)
{
    std::map<std::string, std::vector<std::string>> dependents;
    std::map<std::string, int> waiting;
    for (const auto& line : lines)
    {
        std::size_t colon = line.find(':');
        std::string target = line.substr(0, colon);
        waiting.emplace(target, 0);
        std::istringstream deps(line.substr(colon + 1));
        for (std::string d; deps >> d;)
        {
            waiting.emplace(d, 0);
            dependents[d].push_back(target);
            ++waiting[target];
        }
    }
    std::set<std::string> ready;
    for (const auto& [name, count] : waiting)
        if (count == 0) ready.insert(name);
    std::vector<std::string> order;
    while (!ready.empty())
    {
        std::string name = *ready.begin();
        ready.erase(ready.begin());
        order.push_back(name);
        for (const auto& t : dependents[name])
            if (--waiting[t] == 0) ready.insert(t);
    }
    if (order.size() < waiting.size()) return { "cycle" };
    return order;
}

