static bool isCycle(const std::vector<int>& cyc, const Edges& edges)
{
    if (cyc.empty()) return false;
    for (std::size_t i = 0; i < cyc.size(); ++i)
    {
        std::pair<int, int> e{ cyc[i], cyc[(i + 1) % cyc.size()] };
        if (std::find(edges.begin(), edges.end(), e) == edges.end()) return false;
    }
    return true;
}

TEST("topological order") {
    CHECK_EQ(topoOrder(6, { { 5, 2 }, { 5, 0 }, { 4, 0 }, { 4, 1 }, { 2, 3 }, { 3, 1 } }), (std::vector<int>{ 4, 5, 0, 2, 3, 1 }));
    CHECK_EQ(topoOrder(3, {}), (std::vector<int>{ 0, 1, 2 }));
    CHECK(topoOrder(3, { { 0, 1 }, { 1, 2 }, { 2, 1 } }).empty());
    CHECK_EQ(topoOrder(4, { { 3, 2 }, { 2, 1 }, { 1, 0 } }), (std::vector<int>{ 3, 2, 1, 0 }));
}
TEST("finding a cycle") {
    Edges e{ { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 1 }, { 2, 4 } };
    auto c = findCycle(5, e);
    CHECK(isCycle(c, e));
    CHECK_EQ(c.size(), std::size_t{ 3 });
    CHECK(findCycle(4, { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 } }).empty());
    Edges self{ { 0, 0 } };
    CHECK(isCycle(findCycle(1, self), self));
}
TEST("a cycle of 100,000 vertices") {
    const int n = 100000;
    Edges e;
    for (int i = 0; i < n; ++i) e.push_back({ i, (i + 1) % n });
    auto c = findCycle(n, e);
    CHECK_EQ(c.size(), std::size_t{ n });
    Edges chain;
    for (int i = 0; i + 1 < n; ++i) chain.push_back({ i, i + 1 });
    CHECK(findCycle(n, chain).empty());
}
TEST("counting paths") {
    CHECK_EQ(countPaths(4, { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 } }, 0, 3), 2LL);
    CHECK_EQ(countPaths(4, { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 } }, 3, 0), 0LL);
    CHECK_EQ(countPaths(2, { { 0, 1 }, { 0, 1 } }, 0, 1), 2LL);
    CHECK_EQ(countPaths(1, {}, 0, 0), 1LL);
    Edges ladder;                                            // 61 layers, two ways between each: 2^60 paths
    for (int i = 0; i < 60; ++i) { ladder.push_back({ i, i + 1 }); ladder.push_back({ i, i + 1 }); }
    CHECK_EQ(countPaths(61, ladder, 0, 60), 1LL << 60);
}
TEST("build order") {
    CHECK_EQ(buildOrder({ "app: lib net", "lib: core", "net: core", "core:", "tests: app" }),
             (std::vector<std::string>{ "core", "lib", "net", "app", "tests" }));
    CHECK_EQ(buildOrder({ "b: a", "c:", "a:" }), (std::vector<std::string>{ "a", "b", "c" }));
    CHECK_EQ(buildOrder({ "x: y", "y: z", "z: x" }), (std::vector<std::string>{ "cycle" }));
    CHECK_EQ(buildOrder({ "zeta: alpha" }), (std::vector<std::string>{ "alpha", "zeta" }));
    CHECK(buildOrder({}).empty());
}

